<template>
  <section ref="board" class="qvm-board" aria-label="视频素材台">
    <header><div><span>MIX / A LITTLE OF EVERYTHING</span><h3>{{ title }}</h3></div><b>{{ modelValue.length }} <small>份灵感</small></b></header>
    <p>{{ subtitle }}</p>
    <div class="qvm-tracks">
      <section v-for="track in tracks" :key="track.kind" class="qvm-track" :class="'qvm-'+track.kind" :aria-label="track.label+'素材轨'">
        <header><span class="qvm-token" aria-hidden="true">{{ track.icon }}</span><div><h4>{{ track.label }}</h4><small>{{ track.hint }}</small></div><b>{{ ofKind(track.kind).length }} / {{ limits[track.kind] }}</b></header>
        <div class="qvm-cards">
          <article v-for="(item,index) in ofKind(track.kind)" :key="item.id" class="qvm-card">
            <img v-if="track.kind==='image'&&previews.get(item.id)" :src="previews.get(item.id)" :alt="item.filename || '画面参考'"/>
            <video v-else-if="track.kind==='video'&&previews.get(item.id)" :src="previews.get(item.id)" :data-material-id="item.id" controls playsinline preload="metadata" :aria-label="'预览视频素材 '+(index+1)"></video>
            <audio v-else-if="track.kind==='audio'&&previews.get(item.id)" :src="previews.get(item.id)" :data-material-id="item.id" controls preload="metadata" :aria-label="'预览声音素材 '+(index+1)"></audio>
            <button v-else type="button" class="qvm-placeholder qvm-preview" :disabled="previewing.has(item.id)" :aria-label="'预览'+track.label+'素材 '+(index+1)" @click="preview(item)"><BrandLoader v-if="previewing.has(item.id)" :size="24"/><span v-else aria-hidden="true">{{ track.icon }}</span><small>{{ previewing.has(item.id) ? '正在打开…' : '预览素材' }}</small></button>
            <div class="qvm-caption"><b>{{ track.label }} {{ index+1 }}</b><span>{{ item.filename || '从我的片库带来' }}</span><small v-if="item.duration">{{ Number(item.duration).toFixed(1) }} 秒</small></div>
            <button type="button" class="qvm-remove" :aria-label="'移除'+track.label+'素材 '+(index+1)" :disabled="disabled || busy" @click="remove(item.id)">×</button>
          </article>
          <label v-if="limits[track.kind]" class="qvm-add" :class="{ 'is-disabled': disabled || busy || ofKind(track.kind).length >= limits[track.kind] }"><input type="file" :accept="track.accept" :multiple="limits[track.kind]>1" :disabled="disabled || busy || ofKind(track.kind).length >= limits[track.kind]" :aria-label="'加入'+track.label+'素材'" @change="upload($event,track.kind)"/><span aria-hidden="true">＋</span><b>{{ busy ? '素材准备中…' : '加入'+track.label }}</b><small>{{ track.limit }}</small></label>
        </div>
        <div v-if="track.kind==='video'&&limits.video" class="qvm-library"><select v-model="movieId" aria-label="从当前片库页选择视频" :disabled="disabled || busy"><option value="">也可以从当前片库页带一条过来</option><option v-for="movie in movies" :key="movie.id" :value="movie.id">{{ movie.prompt || '我的成片' }}</option></select><button type="button" :disabled="!movieId || disabled || busy || ofKind('video').length >= limits.video" @click="fromMovie">带入 ↗</button></div>
      </section>
    </div>
    <div v-if="busy" class="qvm-progress" role="status"><BrandLoader :size="20"/>正在检查并私有保存素材…</div>
    <p v-if="error||selectionError" class="qvm-error" role="alert">{{ error || selectionError }}</p>
    <footer>素材保持私有；确认开机后，只发送给你选择的创作服务。{{ mode==='reference' ? '用「图片 1」「视频 1」「声音 1」在描述里指引你的想法。' : '' }}</footer>
  </section>
</template>
<script setup>
import {computed,onBeforeUnmount,onUnmounted,reactive,ref,watch} from 'vue';
import {api,fetchBlob,uploadVideoMaterial} from '../../api/client.js';
import {useAuth} from '../../stores/auth.js';
import {materialLimits,validateVideoMaterials} from '../../lib/video-tools.js';
import BrandLoader from './BrandLoader.vue';
const props=defineProps({modelValue:{type:Array,default:()=>[]},mode:{type:String,default:'reference'},features:{type:Object,default:()=>({})},movies:{type:Array,default:()=>[]},disabled:{type:Boolean,default:false}}),emit=defineEmits(['update:modelValue','busy']);
const board=ref(null),auth=useAuth(),owner=auth.user?.id,previews=reactive(new Map()),previewing=reactive(new Set()),busy=ref(false),error=ref(''),movieId=ref(''),previewControllers=new Map();let alive=true,controller;
const current=()=>alive&&auth.isLoggedIn&&auth.user?.id===owner;
const limits=computed(()=>materialLimits(props.mode,props.features));
const tracks=[{kind:'image',label:'画面',icon:'◈',hint:'颜色、人物、场景与构图',limit:'静态图片 · 每张 10 MB',accept:'image/png,image/jpeg,image/webp,image/gif'},{kind:'video',label:'视频',icon:'▶',hint:'把节奏、动作和镜头带进来',limit:'MP4 · 每条 96 MB',accept:'video/mp4'},{kind:'audio',label:'声音',icon:'≋',hint:'一段话、一阵风，或一点旋律',limit:'MP3 / WAV · 每段 20 MB',accept:'audio/mpeg,audio/mp3,audio/wav,audio/x-wav'}];
const title=computed(()=>({reference:'把灵感，放上同一张桌子。',edit:'这条片子，还能长出新故事。',upscale:'让每一帧，再清楚一点。',lipsync:'让画面，接住这一段声音。'})[props.mode]);
const subtitle=computed(()=>({reference:'画面、动作与声音，自由组合成下一幕。',edit:'加入原片，再用描述告诉我们想改变什么。',upscale:'保留原来的故事，把清晰和细节交给精修。',lipsync:'一条视频，一段声音，让角色自然开口。'})[props.mode]);
const ofKind=kind=>props.modelValue.filter(x=>x.kind===kind);
const selectionError=computed(()=>props.modelValue.length?validateVideoMaterials(props.mode,props.modelValue,props.features):'');
function setBusy(value){busy.value=value;emit('busy',value);}
function stopMedia(id){for(const player of board.value?.querySelectorAll('video,audio')||[])if(!id||player.dataset.materialId===id){player.pause();player.removeAttribute('src');player.load();}}
function remove(id){if(busy.value||props.disabled||!current())return;stopMedia(id);previewControllers.get(id)?.abort();const url=previews.get(id);if(url)URL.revokeObjectURL(url);previews.delete(id);emit('update:modelValue',props.modelValue.filter(x=>x.id!==id));error.value='';}
async function preview(item){if(!current()||previewing.has(item.id)||previews.has(item.id))return;const request=new AbortController();previewControllers.set(item.id,request);previewing.add(item.id);error.value='';try{const blob=await fetchBlob('/api/upload/'+encodeURIComponent(item.id)+'/raw',{signal:request.signal});if(!current()||request.signal.aborted||!props.modelValue.some(x=>x.id===item.id))return;previews.set(item.id,URL.createObjectURL(blob));}catch(e){if(current()&&!request.signal.aborted)error.value=e.message||'预览暂未打开，请稍后重试';}finally{if(previewControllers.get(item.id)===request){previewControllers.delete(item.id);previewing.delete(item.id);}}}
async function upload(event,kind){const files=[...event.target.files||[]];event.target.value='';if(!files.length||busy.value||props.disabled||!current())return;if(ofKind(kind).length+files.length>limits.value[kind]){error.value='素材数量超过这一轨的上限';return;}const maximum=(kind==='video'?96:kind==='image'?10:20)*1024*1024;if(files.some(x=>!x.size||x.size>maximum)){error.value='素材为空或超过单份大小限制';return;}controller?.abort();const active=controller=new AbortController();setBusy(true);error.value='';try{for(const file of files){const result=await uploadVideoMaterial(kind,file,{signal:active.signal});if(!current()||active.signal.aborted)return;if(props.modelValue.some(x=>x.id===result.id))continue;previews.set(result.id,URL.createObjectURL(file));emit('update:modelValue',[...props.modelValue,{...result,kind}]);}}catch(e){if(current()&&!active.signal.aborted)error.value=e.message||'素材暂未保存，请稍后再试';}finally{if(current()&&controller===active)setBusy(false);}}
async function fromMovie(){if(!movieId.value||busy.value||props.disabled||!current())return;controller?.abort();const active=controller=new AbortController();setBusy(true);error.value='';try{const item=await api.post('/video/materials/from-task/'+encodeURIComponent(movieId.value),{}, {signal:active.signal});if(!current()||active.signal.aborted)return;if(props.modelValue.some(x=>x.id===item.id)){error.value='这条成片已经在素材台上';return;}emit('update:modelValue',[...props.modelValue,{...item,kind:'video'}]);movieId.value='';}catch(e){if(current()&&!active.signal.aborted)error.value=e.message;}finally{if(current()&&controller===active)setBusy(false);}}
watch(()=>props.modelValue,items=>{const keep=new Set(items.map(x=>x.id));for(const [id,c]of previewControllers)if(!keep.has(id))c.abort();for(const [id,url]of previews)if(!keep.has(id)){URL.revokeObjectURL(url);previews.delete(id);}}, {deep:false});
onBeforeUnmount(()=>stopMedia());
onUnmounted(()=>{alive=false;controller?.abort();for(const c of previewControllers.values())c.abort();previewControllers.clear();emit('busy',false);for(const url of previews.values())URL.revokeObjectURL(url);previews.clear();});
</script>
<style>
.qvm-board{position:relative;margin:22px 0;padding:24px;border:1px solid var(--qd-edge);border-radius:26px;background:linear-gradient(145deg,rgba(160,137,255,.12),rgba(124,227,205,.06));box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 18px 50px rgba(48,38,99,.06)}.qvm-board>header,.qvm-track>header{display:flex;align-items:center;gap:12px}.qvm-board>header{justify-content:space-between}.qvm-board>header span{font-size:9px;letter-spacing:.15em;opacity:.55}.qvm-board h3{font-size:21px;margin:7px 0}.qvm-board>header>b{font-size:25px;color:var(--qd-brand);white-space:nowrap}.qvm-board small{font-size:11px;font-weight:400}.qvm-board>p,.qvm-board footer{font-size:12px;line-height:1.8;opacity:.7}.qvm-tracks{display:grid;gap:14px}.qvm-track{--track-tint:163,142,244;padding:17px;border:1px solid rgba(var(--track-tint),.23);border-radius:19px;background:rgba(var(--track-tint),.06)}.qvm-video{--track-tint:238,169,103}.qvm-audio{--track-tint:215,128,180}.qvm-track:has(.qvm-cards:empty){display:none}.qvm-token{display:grid;place-items:center;flex:0 0 40px;height:40px;font-size:22px;color:rgb(var(--track-tint));background:linear-gradient(135deg,rgba(255,255,255,.3),rgba(var(--track-tint),.22));border:1px solid rgba(255,255,255,.3);border-radius:12px;transform:rotate(-7deg);box-shadow:4px 6px 12px rgba(var(--track-tint),.15)}.qvm-track h4{font-size:14px;margin:0 0 4px}.qvm-track>header>b{margin-left:auto;font-size:12px;color:rgb(var(--track-tint))}.qvm-track small{opacity:.7}.qvm-cards{display:flex;flex-wrap:wrap;gap:10px;margin-top:15px}.qvm-card,.qvm-add{position:relative;flex:1 1 180px;min-width:0;overflow:hidden;border:1px solid rgba(var(--track-tint),.22);border-radius:15px;background:rgba(255,255,255,.1)}.qvm-card img,.qvm-card video{display:block;width:100%;height:120px;object-fit:contain;background:rgba(12,13,32,.7)}.qvm-card audio{display:block;width:100%;height:54px;margin:24px 0 14px}.qvm-placeholder{display:grid;place-items:center;height:80px;font-size:35px;opacity:.45}.qvm-preview{width:100%;border:0;color:inherit;background:transparent;cursor:pointer;display:flex;flex-direction:column;gap:8px;padding:15px}.qvm-preview:focus-visible{outline:2px solid var(--qd-brand);outline-offset:-3px}.qvm-preview small{font-size:11px}.qvm-caption{display:flex;flex-direction:column;gap:4px;padding:12px}.qvm-caption b{font-size:12px}.qvm-caption span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;opacity:.65}.qvm-remove{position:absolute;top:7px;right:7px;width:32px;height:32px;border:1px solid rgba(255,255,255,.25);border-radius:50%;color:white;background:rgba(18,17,35,.6);backdrop-filter:blur(12px);font-size:20px;cursor:pointer}.qvm-add{display:flex;align-items:center;justify-content:center;flex-direction:column;min-height:140px;padding:14px;border-style:dashed;cursor:pointer;transition:transform .2s,background .2s}.qvm-add:hover{transform:translateY(-3px);background:rgba(var(--track-tint),.16)}.qvm-add input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.qvm-add:focus-within{outline:2px solid var(--qd-brand);outline-offset:3px}.qvm-add>span{font-size:28px;color:rgb(var(--track-tint))}.qvm-add b{margin:7px 0;font-size:12px}.qvm-add.is-disabled{opacity:.4;cursor:default}.qvm-library{display:flex;gap:8px;margin-top:12px}.qvm-library select{width:100%;min-width:0;height:42px;padding:0 10px;border:1px solid var(--qd-edge);border-radius:10px;color:inherit;background:var(--qd-panel)}.qvm-library button{white-space:nowrap;border:0;border-radius:10px;padding:0 14px;color:var(--qd-panel);background:var(--qd-ink);cursor:pointer}.qvm-library button:disabled{opacity:.4}.qvm-progress{display:flex;align-items:center;gap:8px;margin-top:14px;font-size:12px}.qvm-board .qvm-error{opacity:1;color:var(--qd-danger,#db5974)}.qvm-board footer{margin-top:18px;font-size:11px}.qv-workspace .qv-tools-parameters{display:grid;gap:16px;margin-top:20px;padding:20px;border:1px solid var(--qd-edge);border-radius:20px}.qv-workspace .qv-tools-parameters legend{padding:0 8px;font-size:12px;font-weight:700}[data-qg-design=play] .qvm-board{border-radius:10px;box-shadow:5px 6px 0 rgba(35,39,27,.08)}[data-qg-design=play] .qvm-token{border-radius:50%;transform:rotate(8deg)}[data-qg-design=orbit] .qvm-board{background:linear-gradient(150deg,rgba(118,91,217,.14),rgba(50,135,160,.06));backdrop-filter:blur(20px)}
@media(max-width:800px){.qvm-board{padding:18px 13px;border-radius:20px}.qvm-board>header{align-items:flex-start}.qvm-board h3{font-size:18px;line-height:1.55}.qvm-board>header>b{font-size:20px}.qvm-track{padding:14px 10px}.qvm-track>header small{font-size:10px}.qvm-card,.qvm-add{flex-basis:100%}.qvm-library{flex-direction:column}.qvm-library select,.qvm-library button{min-height:48px;font-size:16px}.qvm-remove{width:44px;height:44px}.qvm-add{min-height:120px}.qv-workspace .qv-tools-parameters{padding:18px 12px}}
@media(prefers-reduced-motion:reduce){.qvm-add{transition:none}}[data-qg-motion=quiet] .qvm-add{transition:none}
</style>
